package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject.RetentionDaysErrorsVO;

class RetentionDaysErrorsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of retention days errors of observability config")
  void test_retention_days_errors_value_holder_assign_plain_value() {
    Object holder = new Object();
    RetentionDaysErrorsValueHolder<Object> value = new RetentionDaysErrorsValueHolder<>(holder);
    Assertions.assertSame(holder, value.retentionDaysErrors(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRetentionDaysErrorsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getRetentionDaysErrors().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of retention days errors of observability config")
  void test_retention_days_errors_value_holder_assign_value_object() {
    Object holder = new Object();
    RetentionDaysErrorsValueHolder<Object> value = new RetentionDaysErrorsValueHolder<>(holder);
    RetentionDaysErrorsVO vo = RetentionDaysErrorsVO.from(1);
    Assertions.assertFalse(value.getRetentionDaysErrorsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.retentionDaysErrors(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRetentionDaysErrorsValue().orElseThrow());
    Assertions.assertSame(holder, value.retentionDaysErrors(Optional.empty()));
    Assertions.assertFalse(value.getRetentionDaysErrorsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.retentionDaysErrors(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRetentionDaysErrorsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of retention days errors of observability config against the original")
  void test_retention_days_errors_value_holder_read() {
    Object holder = new Object();
    RetentionDaysErrorsValueHolder<Object> value = new RetentionDaysErrorsValueHolder<>(holder);
    RetentionDaysErrorsVO vo = RetentionDaysErrorsVO.from(1);
    RetentionDaysErrorsVO other = RetentionDaysErrorsVO.from(1);
    ObservabilityConfig original = Mockito.mock(ObservabilityConfig.class);
    Mockito.when(original.getRetentionDaysErrorsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRetentionDaysErrors(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRetentionDaysErrors(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.retentionDaysErrors(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRetentionDaysErrors(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRetentionDaysErrors(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of retention days errors of observability config")
  void test_retention_days_errors_value_holder_unset() {
    Object holder = new Object();
    RetentionDaysErrorsValueHolder<Object> value = new RetentionDaysErrorsValueHolder<>(holder);
    RetentionDaysErrorsVO vo = RetentionDaysErrorsVO.from(1);
    value.retentionDaysErrors(vo);
    Assertions.assertSame(holder,
        value.unsetRetentionDaysErrorsIfMatches("retentionDaysErrors_other"));
    Assertions.assertTrue(value.getRetentionDaysErrorsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRetentionDaysErrorsIfMatches("retentionDaysErrors"));
    Assertions.assertFalse(value.getRetentionDaysErrorsValue().isPresent(),
        "The field name must clear the value");
    value.retentionDaysErrors(vo);
    Assertions.assertSame(holder, value.unsetRetentionDaysErrors());
    Assertions.assertFalse(value.getRetentionDaysErrorsValue().isPresent(),
        "Unset must clear the value");
  }
}
